/// A `add` operand: one variant a case.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AddOperand {
    Imm { imm: u32, sx: u32 },
    Uniform { uniform: u32, sx: u32, size32: u32 },
    Reg { reg: u32, sx: u32, hint: u32, size64: u32, size32: u32 },
}

impl super::UscOperand for AddOperand {
    const ENC: Enc = Enc::Add;

    fn parts(&self) -> (usize, Vec<u32>) {
        match *self {
            Self::Imm { imm, sx } => (0, vec![imm, sx]),
            Self::Uniform { uniform, sx, size32 } => (1, vec![uniform, sx, size32]),
            Self::Reg { reg, sx, hint, size64, size32 } => (2, vec![reg, sx, hint, size64, size32]),
        }
    }

    fn of_parts(case: usize, values: &[u32]) -> Result<Self, mlirformat::Error> {
        Ok(match (case, values) {
            (0, &[imm, sx]) => Self::Imm { imm, sx },
            (1, &[uniform, sx, size32]) => Self::Uniform { uniform, sx, size32 },
            (2, &[reg, sx, hint, size64, size32]) => Self::Reg { reg, sx, hint, size64, size32 },
            _ => return Err(mlirformat::Error(format!("add: case {case} with {} values", values.len()))),
        })
    }
}

impl AddOperand {
    /// Its `reg` field, if its case has one.
    pub fn reg(&self) -> Option<u32> {
        match *self {
            Self::Reg { reg, .. } => Some(reg),
            _ => None,
        }
    }
}

impl AddOperand {
    /// Its `mask` field, if its case has one.
    pub fn mask(&self) -> Option<u32> {
        None
    }
}

impl serde::Serialize for AddOperand {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        super::Usc::serialize_operand(self, s)
    }
}

impl<'de> serde::Deserialize<'de> for AddOperand {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        super::Usc::deserialize_operand(d)
    }
}

